--- a/src/seed.rs
+++ b/src/seed.rs
@@ -170,6 +170,13 @@
             seed = mix(seed, box_ptr as usize as u64);
         }

+        // Temporary diagnostic: preserve per-table randomness and native hashing.
+        #[cfg(feature = "std")]
+        let seed = match std::env::var("DELTA_READER_DIAGNOSTIC_SHARED_SEED").as_deref() {
+            Ok("random") => seed,
+            Ok(value @ ("000000" | "000001" | "000002" | "000003")) => value.parse().unwrap(),
+            _ => panic!("DELTA_READER_DIAGNOSTIC_SHARED_SEED must be random or 000000..000003"),
+        };
         SharedSeed::from_u64(seed)
     }
